public class Main {
    public static void main(String[] args) {
        int[] scores = {85, 92, 78, 95, 88};
        int sum = 0;
        for (int i = 0; i < scores.length; i++) {
            sum += scores[i];
        }
        System.out.println(sum);
    }
}
